import Foundation

// Cloud Infrastructure SDK - Circuit Breaker with Adaptive Timeout
// Manages connection pooling and request routing for distributed services

public enum CircuitState {
    case closed
    case open
    case halfOpen
}

public struct RequestMetrics {
    var successCount: UInt32
    var failureCount: UInt32
    var consecutiveFailures: UInt32
    var totalLatencyMs: UInt64
    var requestCount: UInt32

    public init() {
        successCount = 0
        failureCount = 0
        consecutiveFailures = 0
        totalLatencyMs = 0
        requestCount = 0
    }
}

public class CircuitBreaker {
    private var state: CircuitState = .closed
    private var metrics: RequestMetrics = RequestMetrics()
    private let failureThreshold: UInt32
    private let recoveryTimeout: TimeInterval
    private let maxPoolSize: Int
    private var lastStateChange: Date = Date()
    private let lock = NSLock()

    // Adaptive timeout parameters
    private let baseTimeoutMs: UInt32 = 3000
    private let maxTimeoutMs: UInt32 = 30000
    private let timeoutScaleFactor: UInt32 = 2

    public init(failureThreshold: UInt32 = 5, recoveryTimeout: TimeInterval = 30.0, maxPoolSize: Int = 100) {
        self.failureThreshold = failureThreshold
        self.recoveryTimeout = recoveryTimeout
        self.maxPoolSize = maxPoolSize
    }

    // Computes adaptive timeout based on recent average latency
    // Uses exponential backoff scaled by failure ratio
    private func computeAdaptiveTimeout() -> UInt32 {
        guard metrics.requestCount > 0 else { return baseTimeoutMs }

        let avgLatency = UInt32(min(metrics.totalLatencyMs / UInt64(metrics.requestCount), UInt64(UInt32.max)))
        let failureRatio = computeFailureWeight()

        // Scale timeout: base + (avgLatency * failureWeight * scaleFactor)
        // Use UInt64 intermediate to prevent overflow
        let scaledComponent64 = UInt64(avgLatency) * UInt64(failureRatio) * UInt64(timeoutScaleFactor)
        let scaledComponent = UInt32(min(scaledComponent64, UInt64(UInt32.max)))
        let adaptiveTimeout = baseTimeoutMs.addingReportingOverflow(scaledComponent)

        let result = adaptiveTimeout.overflow ? UInt32.max : adaptiveTimeout.partialValue
        // Cap at maximum
        return min(result, maxTimeoutMs)
    }

    // Computes a weight factor based on failure ratio
    // Returns value between 1 and 10 representing severity
    private func computeFailureWeight() -> UInt32 {
        guard metrics.requestCount > 0 else { return 1 }

        // Calculate percentage of failures (0-100)
        let failurePct = (metrics.failureCount * 100) / metrics.requestCount

        // Map to weight: 1 for 0%, 10 for 100%
        let weight = 1 + (failurePct * 9) / 100
        return max(1, min(weight, 10))
    }

    // Determines if a connection should be allowed based on circuit state
    // and adaptive health scoring
    public func shouldAllowRequest() -> Bool {
        lock.lock()
        defer { lock.unlock() }

        switch state {
        case .closed:
            return true
        case .open:
            let elapsed = Date().timeIntervalSince(lastStateChange)
            if elapsed >= recoveryTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen:
            return true
        }
    }

    // Records a successful request with its latency
    public func recordSuccess(latencyMs: UInt32) {
        lock.lock()
        defer { lock.unlock() }

        metrics.successCount += 1
        metrics.requestCount += 1
        metrics.totalLatencyMs += UInt64(latencyMs)
        metrics.consecutiveFailures = 0

        if state == .halfOpen {
            state = .closed
            lastStateChange = Date()
        }
    }

    // Records a failed request with its latency
    public func recordFailure(latencyMs: UInt32) {
        lock.lock()
        defer { lock.unlock() }

        metrics.failureCount += 1
        metrics.requestCount += 1
        metrics.totalLatencyMs += UInt64(latencyMs)
        metrics.consecutiveFailures += 1

        if metrics.consecutiveFailures >= failureThreshold {
            state = .open
            lastStateChange = Date()
        }
    }

    // Returns the current computed timeout for downstream requests
    public func currentTimeout() -> UInt32 {
        lock.lock()
        defer { lock.unlock() }
        return computeAdaptiveTimeout()
    }

    // Computes pool allocation slots based on health score
    // Used by connection pool manager to size per-endpoint pools
    public func computePoolAllocation() -> Int {
        lock.lock()
        defer { lock.unlock() }

        let timeout = computeAdaptiveTimeout()
        // Allocate pool inversely proportional to timeout
        // Lower timeout = healthier = more connections allocated
        let ratio = Double(baseTimeoutMs) / Double(timeout)
        let allocation = Int(ratio * Double(maxPoolSize))
        return max(1, min(allocation, maxPoolSize))
    }

    // Health check endpoint for monitoring
    public func healthStatus() -> [String: Any] {
        lock.lock()
        defer { lock.unlock() }

        return [
            "state": String(describing: state),
            "successCount": metrics.successCount,
            "failureCount": metrics.failureCount,
            "consecutiveFailures": metrics.consecutiveFailures,
            "adaptiveTimeoutMs": computeAdaptiveTimeout(),
            "poolAllocation": computePoolAllocation()
        ]
    }

    // Reset metrics window (called periodically)
    public func resetMetricsWindow() {
        lock.lock()
        defer { lock.unlock() }

        metrics = RequestMetrics()
    }
}
